from __future__ import print_function

from builtins import object
import re
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from lxml import etree, objectify

logger = BackgroundLogger.Instance()


class lxml_parse(object):

    def get_parsed_xml_object(self, xml_file_path):
        """
        Get parsed xml file obj using lxml external module.

        :param xml_file_path: path to xml file
        :type xml_file_path: str

        """
        parser = etree.XMLParser(remove_comments=True)
        tree = objectify.parse(xml_file_path, parser=parser)
        return tree

    def get_namespace(self, xml_obj):
        try:
            ns_search = re.search(r"\{(.*?)\}.*", xml_obj.getroot().tag)
            if ns_search is not None:
                namespace = ns_search.group(1)
                logger.info("Namespace is '{}'.".format(namespace))
                return namespace
        except Exception as e:
            if "object has no attribute 'getroot'" in e.message:
                logger.info("None namespace is defined. Object is not an XML obj")
                raise ValueError("Object is not an XML obj")
            else:
                logger.info("Error occured in get_namespace() lxml_parsing.py")
                raise e
        logger.info("None namespace is defined.")
        return None

    def get_element_by_xpath(self, xml_obj, xpath):
        """
        Will return xml obj node by its tag.

        :param xml_obj: xml obj parsed via lxml module
        :type xml_obj: lxml.etree._ElementTree
        :param xpath: xpath expression for getting node(s)
        :type xpath: str

        :return xml_obj_list: list of nodes matching xpath expression
        :rtype xml_obj_list: list

        """
        namespace = self.get_namespace(xml_obj)
        if namespace:
            self.remove_namespace(xml_obj, namespace)
        list_of_nodes = xml_obj.xpath(xpath)
        logger.info("List of nodes: {}".format(list_of_nodes))
        return list_of_nodes

    def remove_namespace(self, doc, namespace):
        """
        Remove namespace in the passed xml object in place.

        """
        ns = u'{%s}' % namespace
        nsl = len(ns)
        for elem in doc.getiterator():
            if hasattr(elem.tag, 'startswith'):
                try:
                    elem.tag.startswith(ns)
                    if elem.tag.startswith(ns):
                        elem.tag = elem.tag[nsl:]
                except AttributeError as ex:
                    logger.info("{} for element {} (tag : {})  : {}".format(type(ex).__name__, elem, elem.tag, ex))
                except Exception as ex:
                    logger.info("{} for element {} (tag : {})  : {}".format(type(ex).__name__, elem, elem.tag, ex))

    def get_list_of_nodes_by_xpath(self, xml_obj, xpath):
        try:
            namespace = self.get_namespace(xml_obj)
            if namespace:
                self.remove_namespace(xml_obj, namespace)
            list_of_nodes = xml_obj.xpath(xpath)
            logger.info("List of nodes: {}".format(list_of_nodes))
            return list_of_nodes
        except Exception as e:
            logger.debug("Error {}".format(e))
            return False

    def get_value_by_iteration(self, xml_obj, distname, paramname):
        for element in xml_obj.iter():
            tag_type = type(element.tag).__name__
            if tag_type == 'str' and element.tag.find('managedObject') >= 0:
                if re.match(distname, element.attrib["distName"]):
                    for child in element.iterchildren():
                        if child.attrib['name'] == paramname:
                            return child.text

    def get_full_distname(self, xml_obj, distname_pattern):
        distname_pattern = '/{}'.format(distname_pattern)
        for element in xml_obj.iter():
            tag_type = type(element.tag).__name__
            if tag_type == 'str' and element.tag.find('managedObject') >= 0:
                if element.attrib["distName"].endswith(distname_pattern):
                    return element.attrib["distName"]
                # distname_formatted_pattern = distname_pattern + '$'
                # match = re.search(distname_formatted_pattern, element.attrib["distName"])
                # if match:
        raise Exception('No distname matched in SCF, with pattern {}'.format(distname_pattern))

    def get_full_distname_list_by_regx(self, xml_obj, distname_regex):
        distname_list = []
        distname_regex += '$'                     # Append '$' wild-card char
        for element in xml_obj.iter():
            # logger.info("element tag :: {}".format(str(element.tag)))
            if 'managedObject' in element.tag and re.search(distname_regex, element.attrib["distName"]):
                distname_list.append(element.attrib["distName"])
        return distname_list

    def get_distname_from_parameter_by_iteration(self, xml_obj, param_name, param_val):
        distnames = []
        for element in xml_obj.iter():
            tag_type = type(element.tag).__name__
            if tag_type == 'str' and element.tag.find('managedObject') >= 0:
                distname = element.attrib['distName']
            if 'name' in element.attrib and element.attrib['name'] == param_name and element.text==param_val:
                if distname is not None:
                    distnames.append(distname)
        return distnames
